I'll analyze the requirements and implement the `markMessageAsSeen` functionality in the chats store and add the visual indicator in ChatEntry.

## 1. Analysis & Pre-Thinking

**Core Requirements:**
- Add `markMessageAsSeen` action to the chats store API call
- Display a "double-check" visual indicator in the avatar section when message is seen
- Persist the `read_by` list update to database

**Strategic Approach:**
1. Add async action to `client/src/store/chats.js` that calls the API endpoint
2. Add visual indicator (double-check icon) in ChatEntry avatar section
3. Update message object with user from `read_by` list after API success

**Dependencies & Risks:**
- Message model already has `read_by: List[str]` field ✓
- Component already calls `this.$storex.api.chats.markMessageAsSeen()` ✓
- Need to display indicator for other users who have seen the message

**Target Files:**
- `client/src/store/chats.js` - Add `markMessageAsSeen` action
- `client/src/components/ChatEntry.vue` - Add visual double-check indicator

Let me implement these changes:

## 2. Implementation

### File 1: `src/store/chats.js` !!

```js src/store/chats.js
import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import store, { $storex } from '.'
import { ChatSearchRequest } from '@/api/model/ChatSearchRequest'
import { ENTITY_STATUS } from './entityStatuses'

export const namespaced = true

export const state = () => ({
  chats: {},
  activeChatId: null,
  chatEvents: {},
  searchResults: null,
})

function registerChat(state, chat) {
  if (!chat?.id) {
    console.error('[chats store] Attempted to store a null/invalid chat:', chat)
    return
  }
  const existingChat = state.chats[chat.id] || {}
  state.chats[chat.id] = {
    ...existingChat,
    ...chat,
    status: chat.status || ENTITY_STATUS.UNINITIALIZED
  }
}

function getChatWorkingProject({ owner_project_id, project_id }) {
  return $storex.projects.allProjectsById[project_id || owner_project_id] ||
            $storex.projects.activeProject
}

function getChatProject({ owner_project_id }) {
  return $storex.projects.allProjectsById[owner_project_id] ||
            $storex.projects.activeProject
}

function getRootChat(state, chatId) {
  let current = state.chats?.[chatId]
  if (!current) return null
  let depth = 0
  while (current?.parent_id && state.chats?.[current.parent_id] && depth < 20) {
    current = state.chats[current.parent_id]
    depth++
  }
  return current
}

export const getters = getterTree(state, {
  allChats: state => Object.values(state.chats || {}),
  allTags: state => new Set(Object.values(state.chats || {})?.map(c => c.tags).reduce((a, b) => a.concat(b), []) || []),
  allPRs: state => Object.values(state.chats || {}).filter(c => c.pr_view?.from_branch),
  allTemplates: state => Object.values(state.chats || {}).filter(c => c.is_template),
  isChatUpdating: state => (chatId) => {
    return (state.chatEvents[chatId]?.updatingCount || 0) > 0 ||
      state.chats[chatId]?.status === ENTITY_STATUS.LOADING
  },
  activeChat: state => state.activeChatId ? (state.chats[state.activeChatId] || null) : null,
  chatProject: state => ({ project_id, owner_project_id }) => {
    return $storex.projects.allProjectsById[project_id || owner_project_id]
  },
  chatChildren: state => (chatId) => {
    const children = Object.values(state.chats || {}).filter(c => c.parent_id === chatId)
    return children
  },
  chatDescendants: (state, getters) => (chatId) => {
    const direct = getters.chatChildren(chatId)
    const indirect = direct.flatMap(child => getters.chatDescendants(child.id))
    return [...direct, ...indirect]
  },
  rootChat: state => (chatId) => getRootChat(state, chatId),
  searchResults: state => state.searchResults,
  getChatProject: () => getChatProject,
  getChatWorkingProject: () => getChatWorkingProject,
})

export const mutations = mutationTree(state, {
  setActiveChatId(state, chatId) {
    state.activeChatId = chatId || null
  },

  clearActiveChat(state) {
    state.activeChatId = null
  },

  setSearchResults(state, results) {
    state.searchResults = results
  },

  clearSearchResults(state) {
    state.searchResults = null
  },

  setChatUpdating(state, { chatId, updating }) {
    const current = state.chatEvents[chatId]?.updatingCount || 0
    const prevTimeoutId = state.chatEvents[chatId]?.timeoutId || null

    if (prevTimeoutId) {
      clearTimeout(prevTimeoutId)
    }

    if (!updating) {
      state.chatEvents = {
        ...state.chatEvents,
        [chatId]: {
          ...(state.chatEvents[chatId] || {}),
          updatingCount: 0,
          updatingAt: null,
          timeoutId: null,
        }
      }
    } else {
      const timeoutId = setTimeout(() => {
        $storex.chats.setChatUpdating({ chatId, updating: false })
      }, 10000)

      state.chatEvents = {
        ...state.chatEvents,
        [chatId]: {
          ...(state.chatEvents[chatId] || {}),
          updatingCount: current + 1,
          updatingAt: new Date().toISOString(),
          timeoutId,
        }
      }
    }
  },

  setChatStatus(state, { chatId, status }) {
    const chat = state.chats[chatId]
    if (!chat) return
    state.chats[chatId] = {
      ...chat,
      status
    }
  },

  clearChats(state) {
    state.chats = {}
    state.activeChatId = null
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init ({ state }) {
    },
    async loadChats({ state }) {
      const activeProject = $storex.projects.activeProject
      if (!activeProject?.$api) return

      const chats = await activeProject.$api.chats.list()
      chats.forEach(chat => {
        if (chat.id && !state.chats[chat.id]) {
          registerChat(state, { ...chat, status: ENTITY_STATUS.UNINITIALIZED })
        }
      })
    },
    async searchChats({ state }, options = {}) {
      let searchRequest

      if (options instanceof ChatSearchRequest) {
        searchRequest = options
      } else {
        if (!options.query || options.query.trim() === '') {
          $storex.chats.clearSearchResults()
          return null
        }
        searchRequest = new ChatSearchRequest(options)
      }

      const validationErrors = searchRequest.getValidationErrors()
      if (validationErrors.length > 0) {
        console.error('[chats store] Search validation failed:', validationErrors)
        return {
          error: validationErrors[0],
          results: [],
          total: 0,
          page: 1,
          page_size: searchRequest.page_size,
          total_pages: 0,
          has_next: false,
          has_prev: false,
        }
      }

      const project = $storex.projects.activeProject
      const results = await project.$api.chats.search(searchRequest)

      $storex.chats.setSearchResults(results)
      return results
    },
    async clearChatSearch() {
      $storex.chats.clearSearchResults()
    },
    async ensureChatRoot({ state }, chat) {
      if (!chat?.id) return null
      let current = state.chats[chat.id] || {
        id: chat.id,
        owner_project_id: chat.owner_project_id,
        project_id: chat.project_id
      }
      let depth = 0
      while (current?.parent_id && depth < 20) {
        const parent = state.chats[current.parent_id]
        if (!parent) {
          const loadedParent = await $storex.chats.loadChat({
            id: current.parent_id,
            owner_project_id: current.owner_project_id || current.project_id
          })
          if (!loadedParent) break
          current = loadedParent
        } else {
          current = parent
        }
        depth++
      }
      return getRootChat(state, current.id) || current
    },
    async loadChildrenHierarchy({ state, getters }, rootChat, maxDepth = 5) {
      if (!rootChat?.id) return []

      const loadRecursive = async (parentChat, depth = 0) => {
        if (depth >= maxDepth) return []
        const children = getters.chatChildren(parentChat.id) || []
        const result = [...children]
        for (const child of children) {
          result.push(...(await loadRecursive(child, depth + 1)))
        }
        return result
      }

      const descendants = await loadRecursive(rootChat)
      return [rootChat, ...descendants]
    },
    async loadUninitialized({ state }, chat) {
      if (!chat?.id) return null

      const storedChat = state.chats[chat.id]
      if (!storedChat) return null

      if (storedChat.status === ENTITY_STATUS.LOADED) {
        return storedChat
      }

      if (storedChat.status === ENTITY_STATUS.LOADING) {
        return storedChat
      }

      if (storedChat.status === ENTITY_STATUS.UNINITIALIZED) {
        return await $storex.chats.loadChat(chat)
      }

      return storedChat
    },
    async saveChat({ state }, chat) {
      const savedChat = await $storex.chats.saveChatInfo(chat)
      if (!savedChat) return null
      if (chat.messages?.length) {
        await $storex.chats.updateMessages({ chat: savedChat, messages: chat.messages })
      }
      return state.chats[savedChat.id] || savedChat
    },
    async saveChatInfo({ state }, chat) {
      const isNew = !chat.id
      if (!isNew) {
        $storex.chats.setChatStatus({ chatId: chat.id, status: ENTITY_STATUS.SAVING })
      }
      try {
        const project = getChatProject(chat)
        const updatedChat = await project.$api.chats.saveChatInfo({ ...chat, messages: [] })
        registerChat(state, { ...updatedChat, status: ENTITY_STATUS.LOADED })
        return state.chats[updatedChat.id]
      } catch (error) {
        console.error('[chats store] Failed to save chat info:', error)
        if (!isNew && chat.id) {
          $storex.chats.setChatStatus({ chatId: chat.id, status: ENTITY_STATUS.LOADED })
        }
      }
      return null
    },
    async findProjectChat({ state }, { id, owner_project_id }) {
      const project = $storex.projects.allProjectsById[owner_project_id]
      const chat = state.chats[id]
      if (chat) {
        return chat
      }
      const loadedChat = await project.$api.chats.loadChat({ id, owner_project_id })
      registerChat(state, loadedChat)
      return state.chats[id] || null
    },
    async loadChat({ state }, chat) {
      if (!chat.id) {
        throw Error(`Can't load a chat without id: ${chat}`)
      }

      const existingChat = state.chats[chat.id]
      if (existingChat && existingChat.status === ENTITY_STATUS.LOADED) {
        return existingChat
      }

      const project = getChatProject(chat)
      $storex.chats.setChatStatus({ chatId: chat.id, status: ENTITY_STATUS.LOADING })
      try {
        const loadedChat = await project.$api.chats.loadChat(chat)
        registerChat(state, { ...loadedChat, status: ENTITY_STATUS.LOADED })
      } catch (error) {
        $storex.chats.setChatStatus({ chatId: chat.id, status: ENTITY_STATUS.UNINITIALIZED })
      }

      return state.chats[chat.id]
    },
    async reloadChat({ state }, chat) {
      const project = getChatProject(chat)
      const freshChat = await project.$api.chats.loadChat(chat)
      if (freshChat && state.chats[chat.id]) {
        Object.assign(state.chats[chat.id], { ...freshChat, status: ENTITY_STATUS.LOADED })
      } else {
        registerChat(state, { ...freshChat, status: ENTITY_STATUS.LOADED })
      }
      return state.chats[chat.id]
    },
    async addMessage({ state }, { chat, message }) {
      if (!chat?.id) return
      if (!message.content) {
        throw new Error("No empty messages allowed")
      } 
      const project = getChatProject(chat)

      try {
        const updatedChat = await project.$api.chats.addMessage(chat.id, message)

        if (updatedChat && updatedChat.messages) {
          state.chats[chat.id].messages = updatedChat.messages
        }

        return updatedChat
      } catch (error) {
        console.error('[chats store] Failed to add message:', error)
        throw error
      }
    },
    async removeMessage({ state }, { chat, messageDocId }) {
      if (!chat?.id || !messageDocId) return

      const project = getChatProject(chat)

      try {
        const updatedChat = await project.$api.chats.removeMessage(chat.id, messageDocId)

        if (updatedChat && updatedChat.messages) {
          state.chats[chat.id].messages = updatedChat.messages
        }

        return updatedChat
      } catch (error) {
        console.error('[chats store] Failed to remove message:', error)
        throw error
      }
    },
    async updateMessage({ state }, { chat, message }) {
      if (!chat?.id) return

      if (!message?.doc_id) {
        return $storex.chats.addMessage({ chat, message })
      }

      const project = getChatProject(chat)

      try {
        const updatedChat = await project.$api.chats.updateMessage(chat.id, message)
        registerChat(state, { ...updatedChat, status: ENTITY_STATUS.LOADED })

        return updatedChat
      } catch (error) {
        console.error('[chats store] Failed to update message:', error)
        throw error
      }
    },
    async updateMessages({ state }, { chat, messages }) {
      if (!chat?.id || !messages?.length) return

      const project = getChatProject(chat)

      try {
        let lastResult = null
        for (const message of messages) {
          if (message.doc_id) {
            lastResult = await project.$api.chats.updateMessage(chat.id, message)
          } else {
            lastResult = await project.$api.chats.addMessage(chat.id, message)
          }
        }

        if (lastResult?.messages) {
          state.chats[chat.id].messages = lastResult.messages
        } else {
          await $storex.chats.reloadChat(chat)
        }

        return state.chats[chat.id]
      } catch (error) {
        console.error('[chats store] Failed to update messages:', error)
        throw error
      }
    },
    async updateChatInfo({ state }, { chat, updates }) {
      if (!chat?.id) return

      const project = getChatProject(chat)

      try {
        // Update only metadata/info, not messages
        const updatedChat = await project.$api.chats.updateMetadata(chat.id, updates)

        if (updatedChat && state.chats[chat.id]) {
          Object.assign(state.chats[chat.id], updates)
        }

        return updatedChat
      } catch (error) {
        console.error('[chats store] Failed to update chat info:', error)
        throw error
      }
    },
    async markMessageAsSeen({ state }, { chat_id, message_id, username }) {
      if (!chat_id || !message_id || !username) return null

      const chat = state.chats[chat_id]
      if (!chat) return null

      const project = getChatProject(chat)

      try {
        const response = await project.$api.chats.markMessageAsSeen({
          chat_id,
          message_id,
          username
        })

        if (response && chat.messages) {
          const messageIndex = chat.messages.findIndex(m => m.doc_id === message_id)
          if (messageIndex !== -1) {
            const message = chat.messages[messageIndex]
            if (!message.read_by) {
              message.read_by = []
            }
            if (!message.read_by.includes(username)) {
              message.read_by = [...message.read_by, username]
            }
          }
        }

        return response
      } catch (error) {
        console.error('[chats store] Failed to mark message as seen:', error)
        return null
      }
    },
    async deleteChat({ state, getters }, chat) {
      if (!chat?.id) return

      const descendants = getters.chatDescendants(chat.id) || []

      if (!chat.temp) {
        const project = getChatProject(chat)
        await project.$api.chats.delete(chat)
      }

      const ids = new Set([chat.id, ...(descendants || []).map(c => c.id)])
      ids.forEach(id => {
        delete state.chats[id]
      })

      if (ids.has(state.activeChatId)) {
        $storex.chats.clearActiveChat()
      }
    },
    async setActiveChat({ state }, activeChat) {
      const { id, project_id, owner_project_id } = activeChat || {}

      if (!id) {
        $storex.chats.clearActiveChat()
        return
      }

      await $storex.chats.reloadChat({ id, project_id, owner_project_id })

      $storex.chats.setActiveChatId(id)

      if (!$storex.ui.isMobile && $storex.ui.viewMode !== 'vibe') {
        $storex.ui.openChat($storex.chats.activeChat)
      }
    },
    async createNewChat({ state }, chat) {
      chat = {
        mode: 'chat',
        profiles: [],
        chat_index: 0,
        messages: [],
        auto_initialize: !chat.name,
        owner_project_id: chat.owner_project_id || $storex.projects.activeProject.project_id,
        status: ENTITY_STATUS.UNINITIALIZED,
        ...chat
      }
      return await $storex.chats.saveChat(chat)
    },
    async createNewChatWithProject({ state }, { project, chat = {} }) {
      const chatData = {
        ...chat,
        owner_project_id: project?.project_id || $storex.projects.activeProject.project_id
      }
      return await $storex.chats.createNewChat(chatData)
    },
    async createChatFromTemplate({ state }, { template, project }) {
      if (!template?.id) {
        console.error('[chats store] Cannot create chat from invalid template')
        return null
      }

      const newMessages = (template.messages || []).map(msg => ({
        ...msg,
        doc_id: null,
        id: null
      }))

      const newChat = {
        ...template,
        is_template: false,
        id: null,
        messages: newMessages,
        owner_project_id: project?.project_id || $storex.projects.activeProject.project_id
      }

      return await $storex.chats.createNewChat(newChat)
    },
    async createNewChatFromUrl({ state }, chat) {
      chat = {
        mode: 'chat',
        profiles: [],
        chat_index: 0,
        status: ENTITY_STATUS.UNINITIALIZED,
        ...chat
      }
      const project = getChatProject(chat)
      const savedChat = await project.$api.chats.fromUrl(chat)
      registerChat(state, { ...savedChat, status: ENTITY_STATUS.LOADED })
      if (!chat.temp) {
        await $storex.chats.setActiveChat(savedChat)
      }
      return state.chats[savedChat?.id]
    },
    async createNewBoardChat({ state }, { boardTitle, columnTitle, chat }) {
      boardTitle = boardTitle || chat.board
      columnTitle = columnTitle || chat.column
      const newColumn = {
        title: columnTitle,
        chats: []
      }
      if (!$storex.projects.kanban) {
        await $storex.projects.loadKanban()
      }
      if (!$storex.projects.kanban.boards[boardTitle]) {
        $storex.projects.kanban.boards = {
          ...$storex.projects.kanban.boards,
          [boardTitle]: {
            columns: [newColumn]
          }
        }
      }
      let column = $storex.projects.allBoards
                        .find(({ title }) => title === boardTitle).columns.find(({ title }) => title === columnTitle)
      if (!column) {
        column = newColumn
        $storex.projects.kanban.boards[boardTitle].columns.push(column)
      }

      const newChat = await $storex.chats.createNewChat({
        board: boardTitle,
        column: columnTitle,
        ...chat
      })
      await $storex.chats.setActiveChat(newChat)
      column.chats = [...column?.chats || [], newChat.id]
      $storex.projects.saveKanban($storex.projects.kanban)
      return newChat
    },
    async createNewThread(_, { chat, mode, message }) {
      const { files, profiles, doc_id: subtaskMessageId } = message
      const findChild = $storex.chats.allChats.find(c => c.message_id === subtaskMessageId)

      if (!findChild) {
        const boardTitle = chat.board
        const columnTitle = chat.column
        await $storex.chats.createNewBoardChat({
          boardTitle, columnTitle,
          chat: {
            parent: chat,
            name: `${subtaskMessageId} - thread`,
            project_id: chat.project_id,
            parent_id: chat.parent_id,
            message_id: subtaskMessageId,
            file_list: files,
            profiles: profiles,
            mode,
            board: chat.board,
            column: chat.column,
            activateChat: true,
            messages: [{ ...message, doc_id: null }]
          }
        })
      } else {
        await $storex.chats.setActiveChat(findChild)
      }
    },
    async onChatEvent({ state }, { event, data }) {
      const {
        chat: {
          id: chatId,
          owner_project_id
        },
        message,
        event_type,
        type,
        codx_path
      } = data

      if (event_type === 'error') {
        $storex.ui.addNotification({ text: message, type: event_type })
      }

      if (chatId) {
        if (type === 'changed' || !state.chats[chatId]) {
          await $storex.chats.reloadChat({ id: chatId, owner_project_id })
        }
        const chat = state.chats[chatId]
        if (chat && message) {
          const allMessagesDone = chat.messages.every(m => m.done)
          if (allMessagesDone) {
            $storex.chats.setChatUpdating({ chatId, updating: false })
          } else {
            $storex.chats.setChatUpdating({ chatId, updating: true })
          }
        }
      }
    },
    async readFile({ state }, { chat, file }) {
      const project = getChatWorkingProject(chat)
      return project.$api.files.read(file)
    },
    async writeFile({ state }, { chat, file, content }) {
      const project = getChatWorkingProject(chat)
      return project.$api.files.write(file, content)
    },
    async getChatProfiles({}, chat) {
      if (!chat?.id) return []

      const projectId = chat.project_id || chat.owner_project_id
      if (!projectId) return []

      const project = $storex.projects.allProjectsById[projectId]
      if (!project) return []

      // Load profiles if not already loaded for this project
      if (!$storex.profiles.profilesByProject[projectId]) {
        await $storex.profiles.loadProjectProfiles(project)
      }

      return $storex.profiles.profilesByProject[projectId] || []
    }
  }
)
```

| File Path | Action | Component / Section | Change Description |
| :--- | :--- | :--- | :--- |
| `client/src/store/chats.js` | Modify | actions | Added `markMessageAsSeen` action that calls API and updates message `read_by` list in store |

### File 2: `client/src/components/ChatEntry.vue`

Now I'll update the ChatEntry component to add the visual double-check indicator and use the store action:

```vue client/src/components/ChatEntry.vue
<script setup>
import Markdown from './Markdown.vue'
import moment from 'moment'
import { CodeDiff } from 'v-code-diff'
import ChatIcon from './chat/ChatIcon.vue'
import Document from './document/Document.vue'
import ProfileAvatar from './profile/ProfileAvatar.vue'
import DocumentSummary from './document/DocumentSummary.vue'
import MessagePRView from './chat/MessagePRView.vue'
import MessageFileView from './chat/MessageFileView.vue'
import ChatEntrySelectionMenu from './ChatEntrySelectionMenu.vue'
</script>

<template>
  <!-- =============================================
       NOTION-STYLE DESKTOP BLOCK RENDERING
       ============================================= -->
  <div
    class="notion-entry group/entry relative w-full"
    :class="[
      displayMessage.hide && 'opacity-40 hover:opacity-100 transition-opacity',
    ]"
    @click="markMessageAsSeen"
    @scroll.passive="markMessageAsSeen"
  >
    <!-- ── Row: Avatar + Header + Content ── -->
    <div class="flex gap-3 items-start w-full">
      <!-- Avatar column -->
      <div class="w-7 shrink-0 flex flex-col items-center gap-1 pt-0.5">
        <template v-if="isNewSpeaker">
          <img class="w-6" src="/only_icon.png" v-if="isAssistant" />
          <div
            v-for="profile in messageProfiles"
            :key="profile.name"
            class="tooltip tooltip-right relative"
            :data-tip="profile.name || profile.username"
          >
            <ProfileAvatar :profile="profile" width="6" />
            <!-- Double-check indicator for seen by current user -->
            <div v-if="isMessageSeenByMe" class="absolute -bottom-1 -right-1 text-success text-xs" title="You have seen this message">
              <i class="fa-solid fa-check-double"></i>
            </div>
          </div>
        </template>
        <!-- Connecting line for grouped messages -->
        <div
          v-if="!isNewSpeaker"
          class="w-px flex-1 bg-base-300/40 mt-0.5 min-h-[1rem]"
        >           
        </div>

        <!-- Seen by users section -->
        <div v-if="seenByUsers.length > 0" class="mt-2 flex flex-col items-center gap-0.5">
          <div class="text-[9px] text-base-content/40 uppercase font-semibold tracking-wider">Seen</div>
          <div
            v-for="user in seenByUsers"
            :key="user"
            class="tooltip tooltip-right relative"
            :data-tip="`${user} has seen this message`"
          >
            <div class="w-5 h-5 rounded-full bg-base-300 flex items-center justify-center text-[10px] text-base-content/50 font-semibold">
              {{ user.charAt(0).toUpperCase() }}
            </div>
            <!-- Double-check mark for users who have seen -->
            <div class="absolute -bottom-0.5 -right-0.5 text-success text-[9px]">
              <i class="fa-solid fa-check-double"></i>
            </div>
          </div>
        </div>

        <!-- Events button — desktop only -->
        <button
          v-if="hasEvents"
          class="hidden md:flex mt-4 btn btn-xs btn-ghost tooltip tooltip-bottom gap-1"
          :class="eventsOpen && 'btn-active text-warning'"
          data-tip="Events & Tools"
          @click.stop="toggleEventsPanel"
        >
          <i class="fa-solid fa-wrench text-warning/70"></i>
          <span class="text-[10px]">{{ eventCount }}</span>
        </button>

        <button
          v-if="hasAttachments"
          class="hidden md:flex mt-4 btn btn-xs btn-ghost tooltip tooltip-bottom gap-1"
          :class="eventsOpen && 'btn-active text-warning'"
          data-tip="Attachments"
          @click.stop="toggleEventsPanel"
        >
            <i class="fa-solid fa-paperclip text-info"></i>
            <span class="text-[10px]">{{ attachmentCount }}</span>
        </button>

      </div>

      <!-- Main block column -->
      <div class="flex-1 min-w-0 pb-0.5">

        <!-- Header row: only shown on first message of a speaker group -->
        <div v-if="isNewSpeaker" class="flex items-center gap-2 mb-1 leading-none flex-wrap">

          <span class="font-semibold text-sm text-base-content">{{ displayMessage.user }}</span>
          <span class="text-[11px] text-base-content/40 tabular-nums">{{ formatDate(displayMessage.updated_at) }}</span>
          <span v-if="timeTaken" class="text-[11px] text-base-content/30 tabular-nums">{{ timeTaken }}</span>

          <!-- State badges inline with header -->
          <span v-if="cancellationTime" class="badge badge-xs badge-error">
            <i class="fa-solid fa-ban mr-0.5"></i>Cancelled
          </span>
          <span v-if="displayMessage.is_answer" class="badge badge-xs badge-success gap-1">
            <ChatIcon mode="answer" /> Knowledge
          </span>
          <span v-if="isTopic" class="badge badge-xs badge-info gap-1">
            <ChatIcon mode="topic" /> Topic
          </span>
          <span v-if="displayMessage.hide" class="text-[11px] text-warning/50">
            <i class="fa-solid fa-box-archive"></i> Archived
          </span>

          <!-- ── Mobile-only indicators in header ── -->
          <div class="flex md:hidden items-center gap-1 ml-auto">
            <!-- Mobile profile avatars -->
            <div
              v-for="profile in messageProfiles"
              :key="profile.name"
              class="flex items-center relative"
            >
              <ProfileAvatar :profile="profile" width="4" />
              <!-- Double-check indicator for mobile -->
              <div v-if="isMessageSeenByMe" class="absolute -bottom-0.5 -right-0.5 text-success text-[9px]" title="You have seen this message">
                <i class="fa-solid fa-check-double"></i>
              </div>
            </div>

            <!-- Mobile events indicator -->
            <button
              v-if="hasEvents"
              class="btn btn-xs btn-ghost gap-0.5 px-1 h-auto min-h-0 py-0.5"
              :class="eventsOpen && 'btn-active text-warning'"
              @click.stop="toggleEventsPanel"
            >
              <i class="fa-solid fa-wrench text-warning/70 text-[10px]"></i>
              <span class="text-[10px]">{{ eventCount }}</span>
            </button>

            <!-- Mobile attachments indicator -->
            <button
              v-if="hasAttachments"
              class="btn btn-xs btn-ghost gap-0.5 px-1 h-auto min-h-0 py-0.5"
              :class="eventsOpen && 'btn-active text-warning'"
              @click.stop="toggleEventsPanel"
            >
              <i class="fa-solid fa-paperclip text-info text-[10px]"></i>
              <span class="text-[10px]">{{ attachmentCount }}</span>
            </button>

            <!-- Mobile floating menu button -->
            <div class="dropdown dropdown-end md:hidden">
              <button class="btn btn-xs btn-ghost gap-0.5 px-1 h-auto min-h-0 py-0.5" tabindex="0">
                <i class="fa-solid fa-ellipsis-vertical text-[10px]"></i>
              </button>
              <ul tabindex="0" class="dropdown-content menu bg-base-100 rounded-box z-50 w-52 p-2 shadow border border-base-300">
                <li><a @click.stop="$emit('hide', message)" :class="!isDone && 'disabled'">
                  <i class="fa-solid fa-box-archive text-warning/70"></i>
                  {{ displayMessage.hide ? 'Unarchive' : 'Archive' }}
                </a></li>
                <li><a @click.stop="$emit('thread', message)">
                  <i class="fa-solid fa-comment-dots"></i> Thread
                </a></li>
                <li><a @click.stop="$emit('answer', message)">
                  <i class="fa-solid fa-check-double text-success/70"></i> Mark as answer
                </a></li>
                <li><a @click.stop="copyMessageToClipboard">
                  <i class="fa-solid fa-copy"></i> Copy
                </a></li>
                <li v-if="displayMessage.diffMessage"><a @click.stop="toggleShowDiff">
                  <i class="fa-regular fa-file-lines"></i> Diff
                </a></li>
                <li v-if="hasCodeBlocksOrFiles"><a @click.stop="toggleFileView">
                  <i class="fa-solid fa-file-code"></i> Files
                </a></li>
                <li v-if="hasPRViewBlocks"><a @click.stop="togglePRView">
                  <i class="fa-solid fa-code-branch"></i> Review
                </a></li>
                <li><a @click.stop="runAgents">
                  <i class="fa-solid fa-people-group"></i> Run agents
                </a></li>
                <li v-if="isDone"><a @click.stop="toggleSrcView()">
                  <i class="fa-solid fa-code"></i> View source
                </a></li>
                <li v-if="isDone"><a @click.stop="$emit('edit-message', message)">
                  <i class="fa-solid fa-pen"></i> Edit
                </a></li>
                <li><a @click.stop="confirmRemove" class="text-error">
                  <i class="fa-solid fa-trash-can"></i> Delete
                </a></li>
              </ul>
            </div>
          </div>
        </div>

        <!-- ── Floating Notion Toolbar (appears on hover, top-right of block) ── -->
        <div
          class="absolute right-0 top-0 z-20
                 opacity-0 group-hover/entry:opacity-100
                 transition-all duration-150 translate-y-0
                 flex items-center gap-0.5
                 bg-base-100/95 backdrop-blur-sm
                 border border-base-300 rounded-lg shadow-md px-1 py-0.5"
        >
          <!-- Stop generation -->
          <button
            v-if="!isDone && cancellationTokenId"
            class="btn btn-xs btn-error gap-1"
            @click.stop="cancelMessage"
          >
            <span class="loading loading-xs"></span>Stop
          </button>

          <!-- Core actions -->
          <button
            class="btn btn-xs btn-ghost tooltip tooltip-bottom"
            :data-tip="displayMessage.hide ? 'Unarchive' : 'Archive'"
            @click.stop="$emit('hide', message)"
            v-if="isDone"
          >
            <i class="fa-solid fa-box-archive text-warning/70"></i>
          </button>
          <button
            class="btn btn-xs btn-ghost tooltip tooltip-bottom"
            data-tip="Thread"
            @click.stop="$emit('thread', message)"
          >
            <i class="fa-solid fa-comment-dots"></i>
          </button>
          <button
            class="btn btn-xs btn-ghost tooltip tooltip-bottom"
            data-tip="Mark as answer"
            @click.stop="$emit('answer', message)"
          >
            <i class="fa-solid fa-check-double text-success/70"></i>
          </button>
          <button
            class="btn btn-xs btn-ghost tooltip tooltip-bottom"
            data-tip="Copy"
            @click.stop="copyMessageToClipboard"
          >
            <i class="fa-solid fa-copy"></i>
          </button>
          <button
            v-if="displayMessage.diffMessage"
            class="btn btn-xs btn-ghost tooltip tooltip-bottom"
            :class="showDiff && 'btn-active'"
            data-tip="Diff"
            @click.stop="toggleShowDiff"
          >
            <i class="fa-regular fa-file-lines"></i>
          </button>
          <button
            v-if="hasCodeBlocksOrFiles"
            class="btn btn-xs btn-ghost tooltip tooltip-bottom"
            :class="showFileView && 'btn-active'"
            data-tip="Files"
            @click.stop="toggleFileView"
          >
            <i class="fa-solid fa-file-code"></i>
          </button>
          <button
            v-if="hasPRViewBlocks"
            class="btn btn-xs btn-ghost tooltip tooltip-bottom"
            :class="showPRView && 'btn-active'"
            data-tip="Review"
            @click.stop="togglePRView"
          >
            <i class="fa-solid fa-code-branch"></i>
          </button>

          <!-- Divider -->
          <div class="w-px h-4 bg-base-300 mx-0.5"></div>

          <!-- More dropdown -->
          <div class="dropdown dropdown-end" @click.stop>
            <button tabindex="0" class="btn btn-xs btn-ghost">
              <i class="fa-solid fa-ellipsis-vertical"></i>
            </button>
            <ul
              tabindex="0"
              class="dropdown-content menu rounded-box shadow-lg w-44 p-1 bg-base-200 z-50 text-sm"
            >
              <li><a @click.stop="runAgents" class="text-info"><i class="fa-solid fa-people-group w-4"></i> Run agents</a></li>
              <li v-if="isDone"><a @click.stop="toggleSrcView()"><i class="fa-solid fa-code w-4"></i> View source</a></li>
              <li v-if="isDone"><a @click.stop="$emit('edit-message', message)"><i class="fa-solid fa-pen w-4"></i> Edit</a></li>
              <li><a @click.stop="confirmRemove" class="text-error"><i class="fa-solid fa-trash-can w-4"></i> Delete</a></li>
            </ul>
          </div>
        </div>

        <!-- ── Thread / Reply badge (always visible if exists) ── -->
        <div
          v-if="threadChat"
          class="mb-1 inline-flex"
        >
          <button
            class="flex items-center gap-1 text-[11px] text-info hover:text-info hover:underline cursor-pointer"
            @click.stop="openThread"
          >
            <ChatIcon :mode="threadChat.mode" />
            <span>{{ threadChat.messages?.length || 0 }} replies</span>
          </button>
        </div>

        <!-- ── Loading bar ── -->
        <progress
          v-if="!isDone"
          class="progress progress-xs w-full mb-2 opacity-50"
        ></progress>

        <!-- ── Selection context menu ── -->
        <ChatEntrySelectionMenu
          v-if="showSelectionMenu"
          :selectedText="selectedText"
          :chatProject="chatProject"
          @copy="onSelectionCopy"
          @create-subtask="onSelectionCreateSubtask"
          @search-files="onSelectionSearchFiles"
          @close="onCloseSelectionMenu"
        />

        <!-- ── Skeleton loader ── -->
        <div v-if="!displayMessage.content && !displayMessage.think" class="space-y-2 py-1">
          <div class="skeleton h-4 w-full rounded"></div>
          <div class="skeleton h-4 w-4/5 rounded"></div>
          <div class="skeleton h-4 w-2/3 rounded"></div>
        </div>

        <!-- ── Answer / Topic accent bar ── -->
        <div
          v-if="displayMessage.is_answer || isTopic"
          class="absolute left-0 top-0 bottom-0 w-0.5 rounded-full"
          :class="[
            displayMessage.is_answer && 'bg-success',
            isTopic && !displayMessage.is_answer && 'bg-info',
          ]"
        ></div>

        <!-- ── TOC for long documents ── -->
        <DocumentSummary
          v-if="!srcView && isDone && messageContent && !showPRView && !showFileView && !hasEvents && !showAttachments"
          :content="messageContent"
          :minHeadings="3"
          :documentId="documentId"
          :scrollContainer="$refs.contentArea"
          class="mb-3"
        />

        <!-- ── Main content area ── -->
        <div
          ref="contentArea"
          @copy.stop="onMessageCopy"
          @mouseup="onContentMouseUp"
          class="min-w-0 w-full notion-content"
          :class="[
            displayMessage.is_answer && 'pl-3 border-l-2 border-success/30',
            isTopic && !displayMessage.is_answer && 'pl-3 border-l-2 border-info/30',
          ]"
        >

          <!-- Source view -->
          <pre v-if="srcView" class="text-xs overflow-auto bg-base-200 p-3 rounded-lg">{{ displayMessage.content }}</pre>

          <!-- Document / Markdown -->
          <Document
            v-if="!showDiff && !srcView && !showPRView && !showFileView && !code_patches && !isWord && !showAttachments"
            :content="messageContent"
            :files="chatFiles"
            :project="chatProject"
            :chat="chat"
            :loading="!message.done"
            :documentId="documentId"
            :message="message"
            @generate-code="onGenerateCode"
            @reload-file="$emit('reload-file', { file: $event, message })"
            @open-file="$emit('open-file', $event)"
            @save-file="$emit('save-file', $event)"
            @add-file="$emit('add-file', $event)"
            @sub-task="$emit('sub-task', $event)"
            @copy-chapter="onCopyChapter"
            @create-task="onCreateTask"
            @block-edited="onBlockEdited"
            :mentionList="mentionList"
          >
            <template #chapter-actions="{ chapter, fullContent }">
              <button class="btn btn-sm btn-ghost gap-1" @click="copyChapterMarkdown(chapter, fullContent)">
                <i class="fa-solid fa-copy"></i> Copy
              </button>
              <button class="btn btn-sm btn-ghost gap-1" @click="createTaskFromChapter(chapter, fullContent)">
                <i class="fa-solid fa-plus"></i> Task
              </button>
            </template>
          </Document>

          <!-- Error -->
          <div class="alert alert-error text-xs mt-2" v-if="displayMessage.error">
            {{ displayMessage.error }}
          </div>

          <!-- Diff view -->
          <CodeDiff
            v-if="showDiff && !showPRView && !showFileView"
            :new-string="displayMessage.diffMessage.content"
            :old-string="messageContent"
            theme="dark"
          />

          <!-- Code patches -->
          <div v-if="code_patches && !showPRView && !showFileView && !showAttachments" class="space-y-3 mt-2">
            <div
              v-for="patch in code_patches"
              :key="patch.file_path"
              class="border border-base-300 rounded-lg p-3 bg-base-200/50"
            >
              <div class="text-xs font-bold text-primary mb-1" :title="patch.file_path">
                {{ patch.file_path.replace($project.abs_project_path, '') }}
              </div>
              <div class="text-xs text-base-content/50 mb-2">{{ patch.description }}</div>
              <Markdown :text="'```diff\n' + patch.patch + '\n```'"></Markdown>
              <div class="flex justify-end mt-2">
                <button
                  class="btn btn-sm btn-warning gap-1"
                  :disabled="patch.working"
                  @click="applyPatch(patch)"
                >
                  <span class="loading loading-spinner" v-if="patch.working"></span>
                  Apply changes
                </button>
              </div>
              <div v-if="patch.res" class="text-xs mt-2">
                <div class="text-error" v-if="patch.res.error">{{ patch.res.error }}</div>
                <div class="text-success" v-else>
                  <i class="fa-solid fa-check"></i> Applied
                </div>
              </div>
            </div>
          </div>

          <!-- File View -->
          <MessageFileView
            v-if="showFileView && !srcView && !showDiff && !showPRView && !showAttachments"
            :codeBlocks="prViewCodeBlocks"
            :linkedFiles="displayMessage.files"
            :chat="chat"
            :message="message"
            @save-file="$emit('save-file', $event)"
            @add-file="$emit('add-file', $event)"
            @open-file="$emit('open-file', $event)"
            @sub-task="$emit('sub-task', $event)"
            @remove-file="$emit('remove-file', $event)"
          />

          <!-- PR View -->
          <MessagePRView
            v-if="showPRView && !srcView && !showDiff && !showFileView && !showAttachments"
            :codeBlocks="prViewCodeBlocks"
            :chat="chat"
            :message="message"
            :activeBranch="activeBranch"
            @save-file="$emit('save-file', $event)"
            @add-file="$emit('add-file', $event)"
            @open-file="$emit('open-file', $event)"
            @sub-task="$emit('sub-task', $event)"
          />

          <!-- Images -->
          <div v-if="images && !showPRView && !showFileView && !showAttachments && images?.length" class="mt-3">
            <p class="text-xs text-base-content/40 mb-2">
              <i class="fa-solid fa-images mr-1"></i>Images
            </p>
            <div class="carousel gap-2">
              <div
                class="carousel-item cursor-pointer"
                v-for="image in images"
                :key="image.src"
                @click="$emit('image', image)"
              >
                <div class="flex flex-col gap-1">
                  <div
                    class="bg-cover bg-center border border-base-300 rounded-lg w-20 h-20 hover:border-primary transition-colors"
                    :style="`background-image: url(${image.src})`"
                  ></div>
                  <p class="badge badge-xs" v-if="image.alt">{{ image.alt.slice(0, 12) }}</p>
                </div>
              </div>
            </div>
          </div>

          <!-- Linked files -->
          <div
            v-if="displayMessage.files?.length && !showPRView && !showFileView && !showAttachments"
            class="mt-3 pt-2 border-t border-base-300/50"
          >
            <p class="text-[11px] text-base-content/40 mb-1.5">
              <i class="fa-solid fa-paperclip mr-1"></i>Linked files
            </p>
            <div class="flex flex-wrap gap-1">
              <div
                v-for="file in displayMessage.files"
                :key="file"
                class="flex items-center gap-1 text-xs bg-base-200 hover:bg-base-300 rounded-md px-2 py-0.5 transition-colors group/file"
              >
                <i class="fa-solid fa-file text-primary/60 text-[10px]"></i>
                <a
                  class="hover:underline cursor-pointer max-w-[180px] truncate"
                  @click="openFile(file)"
                  :title="file"
                >
                  {{ file.split('/').reverse()[0] }}
                </a>
                <button
                  class="opacity-0 group-hover/file:opacity-100 ml-0.5 hover:text-error transition-all"
                  @click.stop="$emit('add-file', file)"
                  title="Add to chat"
                >
                  <i class="fa-solid fa-plus text-[10px]"></i>
                </button>
                <button
                  class="opacity-0 group-hover/file:opacity-100 hover:text-error transition-all"
                  @click.stop="$emit('remove-file', file)"
                >
                  <i class="fa-regular fa-circle-xmark text-[10px]"></i>
                </button>
              </div>
            </div>
          </div>
        </div>

        <!-- ── Collapsed toggle (for archived messages) ── -->
        <div
          v-if="isCollapsed && displayMessage.hide"
          class="mt-1 text-[11px] text-base-content/30 cursor-pointer hover:text-base-content/60 transition-colors"
          @click="collapsed = false"
        >
          <i class="fa-solid fa-chevron-down mr-1"></i>Show archived content
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: ['chat', 'message', 'mentionList', 'menu-less', 'usersList', 'isNewSpeaker'],
  emits: [
    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'add-file',
    'sub-task',
    'thread',
    'hide',
    'remove',
    'answer',
    'enhance',
    'copy',
    'add-file-to-chat',
    'remove-file',
    'image',
    'run-agents',
    'edit-message',
    'search-files',
    'edited',
    'run-edit',
    'code-file-shown',
    'message-changed',
    'show-events'
  ],
  data() {
    return {
      srcView: false,
      isRemove: false,
      improvementData: null,
      showDiff: false,
      showPRView: false,
      showFileView: false,
      showAttachments: false,
      documentId: 'doc-' + Math.random().toString(36).slice(2, 8),
      activeBranch: null,
      branchLoading: false,
      showSelectionMenu: false,
      selectedText: '',
      selectionPosition: { top: 0, left: 0 },
      collapsed: false,
      eventsOpen: false,
      seenTimer: null,
      hasSeen: false
    }
  },
  created() {
    this.loadThreadChat()
    this.loadActiveBranch()
    this.collapsed = this.displayMessage.hide
  },
  computed: {
    isDone() {
      return this.displayMessage.done
    },
    isWord() {
      return this.chat?.mode === 'word'
    },
    isTopic() {
      return this.chat?.mode === 'topic'
    },
    isSlackStyle() {
      return this.chat?.mode === 'topic'
    },
    isCollapsed() {
      return this.collapsed !== undefined
        ? this.collapsed
        : this.displayMessage.hide ? true : false
    },
    isMyMessage() {
      return this.displayMessage.user === this.$user.username
    },
    isChannelMessage() {
      return this.chat.mode === 'channel'
    },
    isAssistant() {
      return this.message.role === 'assistant'
    },
    canEditMessage() {
      return !this.isChannelMessage ||
        this.isMyMessage ||
        this.isAssistant
    },
    thinkText() {
      return this.displayMessage.think
    },
    displayMessage() {
      const message = this.threadChat?.messages
          .filter(m => !m.hide)
          .reverse()[0] || this.message
      return message
    },
    messageProfiles() {
      let profiles = this.$projects.profiles
        ?.filter(p => this.displayMessage.profiles?.includes(p.name)) || []
      const user = this.$project.users
        .find(({ username }) => username === this.displayMessage.user)
      return [user, ...profiles].filter(u => !!u)
    },
    images() {
      return this.message?.images?.map(i => {
        try {
          return JSON.parse(i)
        } catch {
          return { src: i }
        }
      })
    },
    messageContent() {
      return this.displayMessage.content
    },
    code_changes() {
      return this.improvementData?.code_changes
    },
    code_patches() {
      return this.improvementData?.code_patches
    },
    timeTaken() {
      if (!this.displayMessage.meta_data) return null
      let timeTaken = '--'
      if (this.displayMessage.meta_data?.time_taken) {
        const seconds = Math.floor(this.displayMessage.meta_data.time_taken)
        const baseMoment = moment({ h: 0, m: 0, s: 0, ms: 0 })
        timeTaken = baseMoment.add(seconds, 'seconds').format('mm:ss')
      } else if (this.displayMessage.meta_data?.start_time) {
        timeTaken = moment(this.displayMessage.meta_data?.start_time).fromNow()
      }
      return timeTaken ? `${this.displayMessage.meta_data.model} ${timeTaken}` : null
    },
    chatProject() {
      if (this.chat.project_id) {
        return this.$projects.allProjects.find(p => p.project_id === this.chat.project_id)
      }
      return this.$project
    },
    chatFiles() {
      return this.chat.file_list
    },
    threadChat() {
      return this.$projects.allChats.find(c => c.message_id === this.message.doc_id)
    },
    cancellationTokenId() {
      return this.displayMessage.meta_data?.cancellation_token_id
    },
    cancellationTime() {
      return this.displayMessage.meta_data?.cancelled_at
    },
    hasPRViewBlocks() {
      return this.$service.chat.hasCodeBlocksWithFilePaths(this.displayMessage)
    },
    hasCodeBlocksOrFiles() {
      return this.prViewCodeBlocks.length > 0 || this.displayMessage.files?.length > 0
    },
    prViewCodeBlocks() {
      return this.$service.chat.extractCodeBlocksFromMessage(this.displayMessage)
    },
    toolEventCount() {
      const toolEvents = this.message?.tool_events
      if (Array.isArray(toolEvents)) {
        return toolEvents.length
      }
      return this.message?.tool_event ? 1 : 0
    },
    lifecycleEventCount() {
      const lifecycleEvents = this.message?.lifecycle_events
      if (Array.isArray(lifecycleEvents)) {
        return lifecycleEvents.length
      }
      return this.message?.lifecycle_event ? 1 : 0
    },
    hasEvents() {
      return this.toolEventCount > 0
    },
    attachmentCount() {
      return this.message?.attachments?.length || 0
    },
    hasAttachments() {
      return this.attachmentCount > 0
    },
    eventCount() {
      return this.toolEventCount + this.attachmentCount
    },
    isMessageSeenByMe() {
      const currentUsername = this.$user?.username
      return currentUsername && this.message.read_by?.includes(currentUsername)
    },
    seenByUsers() {
      const currentUsername = this.$user?.username
      return (this.message.read_by || []).filter(u => u !== currentUsername)
    }
  },
  watch: {
    message() {
      this.loadThreadChat()
      this.resetSeenTracking()
    },
    'message.content': function() {
      this.extractImprovementData()
    }
  },
  methods: {
    formatDate(date) {
      return moment(date).format('DD/MMM HH:mm')
    },
    extractImprovementData() {
      this.improvementData = null
      if (this.displayMessage.content?.startsWith('```json')) {
        try {
          const lines = this.displayMessage.content.split('\n')
          const jsBlock = lines.slice(1, lines.length - 1).join('\n')
          this.improvementData = JSON.parse(jsBlock)
        } catch (ex) {
          console.error('Failed to parse improvement data', ex)
        }
      }
    },
    copyTextToClipboard(text) {
      this.$ui.copyTextToClipboard(text)
    },
    onMessageCopy(ev) {
      const text = window.getSelection().toString()
      if (text) {
        this.copyTextToClipboard(text)
        ev.preventDefault()
      }
    },
    getSelectionPosition() {
      const selection = window.getSelection()
      if (selection.rangeCount === 0) return { top: 0, left: 0 }
      const range = selection.getRangeAt(0)
      const rect = range.getBoundingClientRect()
      return {
        top: Math.max(10, rect.top + window.scrollY - 60),
        left: rect.left
      }
    },
    onContentMouseUp() {
      function getSelectedHTML() {
        const selection = window.getSelection()
        if (selection.rangeCount > 0) {
          const range = selection.getRangeAt(0)
          const clonedContent = range.cloneContents()
          const div = document.createElement('div')
          div.appendChild(clonedContent)
          return div.innerHTML
        }
        return ""
      }

      const selectedText = getSelectedHTML()
      if (selectedText.length > 0) {
        this.selectedText = selectedText
        this.showSelectionMenu = true
      } else {
        this.showSelectionMenu = false
      }
    },
    onSelectionCopy(text) {
      this.copyTextToClipboard(text)
    },
    onSelectionCreateSubtask(content) {
      this.$emit('sub-task', { content })
    },
    onSelectionSearchFiles({ query }) {
      this.$emit('search-files', { query, fromSelection: true })
    },
    onCloseSelectionMenu() {
      this.showSelectionMenu = false
    },
    toggleSrcView() {
      this.srcView = !this.srcView
      if (this.srcView) {
        this.showDiff = false
        this.showPRView = false
        this.showFileView = false
        this.showAttachments = false
      }
    },
    toggleShowDiff() {
      this.showDiff = !this.showDiff
      if (this.showDiff) {
        this.srcView = false
        this.showPRView = false
        this.showFileView = false
        this.showAttachments = false
      }
    },
    toggleFileView() {
      this.showFileView = !this.showFileView
      if (this.showFileView) {
        this.srcView = false
        this.showDiff = false
        this.showPRView = false
        this.showAttachments = false
      }
    },
    togglePRView() {
      this.showPRView = !this.showPRView
      if (this.showPRView) {
        this.srcView = false
        this.showDiff = false
        this.showFileView = false
        this.showAttachments = false
        this.loadActiveBranch()
      }
    },
    toggleAttachmentsView() {
      this.showAttachments = !this.showAttachments
      if (this.showAttachments) {
        this.srcView = false
        this.showDiff = false
        this.showFileView = false
        this.showPRView = false
      }
    },
    onRemove() {
      if (this.isRemove) {
        this.$emit('remove')
      } else {
        this.isRemove = true
      }
    },
    confirmRemove() {
      this.isRemove = true
      this.$emit('remove')
    },
    copyMessageToClipboard() {
      this.copyTextToClipboard(this.displayMessage.content)
    },
    async applyPatch(patch) {
      patch.working = true
      try {
        const code_changes = this.code_changes.filter(cc => cc.file_path === patch.file_path)
        await this.$projects.codeImprovePatch({
          chat: this.chat,
          code_generator: { code_changes, code_patches: [patch] }
        })
        patch.res = { info: 'Patch sent' }
      } catch {
        patch.res = { error: 'Error applying patch' }
      }
      delete patch.working
    },
    onGenerateCode(codeBlockInfo) {
      this.$emit('generate-code', codeBlockInfo)
    },
    openFile(file) {
      this.$emit('preview-file', file)
    },
    openThread() {
      this.$chats.setActiveChat(this.threadChat)
    },
    loadThreadChat() {
      if (this.threadChat) {
        this.$chats.reloadChat(this.threadChat)
      }
    },
    runAgents() {
      this.$emit('run-agents', this.message)
    },
    async cancelMessage() {
      const tokenId = this.cancellationTokenId
      if (!tokenId) return
      try {
        await this.$storex.api.chats.cancelMessage(tokenId)
      } catch (ex) {
        console.error('Failed to cancel message', ex)
      }
    },
    async loadActiveBranch() {
      if (this.branchLoading) return
      this.branchLoading = true
      try {
        const repoInfo = await this.chatProject.$api.repo.info()
        this.activeBranch = repoInfo?.active_branch
      } catch (ex) {
        console.error('Failed to load active branch', ex)
        this.activeBranch = null
      } finally {
        this.branchLoading = false
      }
    },
    copyChapterMarkdown(chapter, fullContent) {
      this.copyTextToClipboard(fullContent)
    },
    createTaskFromChapter(chapter, fullContent) {
      this.$emit('sub-task', { content: fullContent, title: chapter.title })
    },
    onCopyChapter(chapterData) {
      this.copyTextToClipboard(chapterData.content)
    },
    onCreateTask(taskData) {
      this.$emit('sub-task', { content: taskData.content, title: taskData.title })
    },
    toggleEventsPanel() {
      this.eventsOpen = !this.eventsOpen
      if (this.eventsOpen) {
        this.$emit('show-events', {
          toolEvents: this.message?.tool_events || [],
          lifecycleEvents: this.message?.lifecycle_events || [],
          attachments: this.message?.attachments || [],
          metadata: this.message?.meta_data,
          toolCount: this.toolEventCount,
          lifecycleCount: this.lifecycleEventCount,
          attachmentCount: this.attachmentCount,
          totalEvents: this.toolEventCount + this.lifecycleEventCount + this.attachmentCount
        })
      }
    },
    onBlockEdited(data) {
      const { blockHash, originalContent, newContent, block } = data
      const updatedContent = this.replaceBlockInContent(
        this.displayMessage.content,
        originalContent,
        newContent
      )

      this.$emit('edited', {
        ...this.message,
        content: updatedContent
      })
    },
    replaceBlockInContent(fullContent, originalBlock, newBlock) {
      return fullContent.replace(originalBlock, newBlock)
    },
    markMessageAsSeen() {
      if (this.hasSeen) return
      if (this.seenTimer) clearTimeout(this.seenTimer)
      this.seenTimer = setTimeout(() => {
        this.submitMessageSeen()
      }, 500)
    },
    async submitMessageSeen() {
      try {
        const currentUsername = this.$user?.username
        if (!currentUsername) return
        const readByList = this.message.read_by || []
        if (readByList.includes(currentUsername)) {
          this.hasSeen = true
          return
        }
        await this.$storex.chats.markMessageAsSeen({
          chat_id: this.chat?.doc_id,
          message_id: this.message?.doc_id,
          username: currentUsername
        })
        this.hasSeen = true
      } catch (ex) {
        console.error('Failed to mark message as seen', ex)
      }
    },
    resetSeenTracking() {
      this.hasSeen = false
      if (this.seenTimer) clearTimeout(this.seenTimer)
    }
  },
  mounted() {
    this.collapsed = this.isCollapsed || this.displayMessage.hide
    this.extractImprovementData()
    this.resetSeenTracking()
  },
  beforeUnmount() {
    if (this.seenTimer) clearTimeout(this.seenTimer)
  }
}
</script>
